        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://hi.wikiquote.org/wiki/जयशंकर_प्रसाद", Text = "अत्याचार के श्मशान में ही मंगल का, शिव का, सत्य-सुन्दर संगीत का शुभारम्भ होता है।", Author = "जयशंकर प्रसाद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/जयशंकर_प्रसाद", Text = "अन्य देश मनुष्यों की जन्मभूमि हैं, लेकिन भारत मानवता की जन्मभूमि है।", Author = "जयशंकर प्रसाद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/जयशंकर_प्रसाद", Text = "अपने कुकर्मों का फल चखने में कड़वा, परन्तु परिणाम में मधुर होता है।", Author = "जयशंकर प्रसाद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/जयशंकर_प्रसाद", Text = "अर्थ देकर विजय खरीदना देश की वीरता के प्रतिकूल है।", Author = "जयशंकर प्रसाद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/जयशंकर_प्रसाद", Text = "असम्भव कहकर किसी काम को करने से पहले, कर्मक्षेत्र में कांपकर लड़खडाओ मत।", Author = "जयशंकर प्रसाद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/जयशंकर_प्रसाद", Text = "आतंक का दमन करना प्रत्येक राजपुरुष का कर्म है।", Author = "जयशंकर प्रसाद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/जयशंकर_प्रसाद", Text = "आत्म सम्मान के लिए मर मिटना ही दिव्य जीवन है।", Author = "जयशंकर प्रसाद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/जयशंकर_प्रसाद", Text = "इस भीषण संसार में एक प्रेम करनेवाले ह्रदय को दबा देना सबसे बड़ी हानि है।", Author = "जयशंकर प्रसाद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/जयशंकर_प्रसाद", Text = "उत्पीडन की चिनगारी को अत्याचारी अपने ही अंचल में छिपाए रखता है।", Author = "जयशंकर प्रसाद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/जयशंकर_प्रसाद", Text = "ऐसा जीवन तो विडम्बना है, जिसके लिए रात-दिन लड़ना पड़े।", Author = "जयशंकर प्रसाद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/जयशंकर_प्रसाद", Text = "कभी कभी मौन रह जान बुरी बात नहीं है।", Author = "जयशंकर प्रसाद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/जयशंकर_प्रसाद", Text = "कविता करना अत्यन्त पुण्य का फल है।", Author = "जयशंकर प्रसाद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/जयशंकर_प्रसाद", Text = "किसी के उजड़ने से ही कोई दूसरा बसता है।", Author = "जयशंकर प्रसाद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/जयशंकर_प्रसाद", Text = "क्षणिक संसार! इस महाशून्य में तेरा इंद्रजाल किसे भ्रांत नहीं करता?", Author = "जयशंकर प्रसाद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/जयशंकर_प्रसाद", Text = "क्षमा पर केवल मनुष्य का अधिकार है, वह हमें पशु के पास नहीं मिलती।", Author = "जयशंकर प्रसाद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/जयशंकर_प्रसाद", Text = "जागृत राष्ट्र में ही विलास और कलाओं का आदर होता है।", Author = "जयशंकर प्रसाद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/जयशंकर_प्रसाद", Text = "जिस वस्तु को मनुष्य दे नहीं सकता, उसे ले लेने की स्पर्धा से बढ़कर दूसरा दंभ नहीं।", Author = "जयशंकर प्रसाद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/जयशंकर_प्रसाद", Text = "जिसकी भुजाओं में दम न हो, उसके मस्तिष्क में तो कुछ होना ही चाहिए।", Author = "जयशंकर प्रसाद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/जयशंकर_प्रसाद", Text = "जीवन की सबसे बड़ी उपलब्धि है प्रसन्नता। यह जिसने हासिल कर ली, उसका जीवन सार्थक हो गया।", Author = "जयशंकर प्रसाद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/जयशंकर_प्रसाद", Text = "जीवन विश्व की संपत्ति है।", Author = "जयशंकर प्रसाद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/जयशंकर_प्रसाद", Text = "जो अपने कर्मों को इश्वर का कर्म समझकर करता है, वही ईश्वर का अवतार है।", Author = "जयशंकर प्रसाद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/जयशंकर_प्रसाद", Text = "जो आज गुलाम है, वही कल सुलतान हो सकता है।", Author = "जयशंकर प्रसाद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/जयशंकर_प्रसाद", Text = "दो प्यार करनेवाले हृदयों के बीच में स्वर्गीय ज्योति का निवास होता है।", Author = "जयशंकर प्रसाद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/जयशंकर_प्रसाद", Text = "पढाई सभी कामों में सुधार लाना सिखाती है।", Author = "जयशंकर प्रसाद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/जयशंकर_प्रसाद", Text = "पराधीनता से बढ़कर विडम्बना और क्या है?", Author = "जयशंकर प्रसाद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/जयशंकर_प्रसाद", Text = "पुरुष क्रूरता है तो स्त्री करुणा है।", Author = "जयशंकर प्रसाद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/जयशंकर_प्रसाद", Text = "प्रत्येक स्थान और समय बोलने योग्य नहीं रहते।", Author = "जयशंकर प्रसाद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/जयशंकर_प्रसाद", Text = "प्रमाद में मनुष्य कठोर सत्य का भी अनुभव नहीं कर सकता।", Author = "जयशंकर प्रसाद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/जयशंकर_प्रसाद", Text = "प्रश्न स्वयं कभी किसी के सामने नहीं आते।", Author = "जयशंकर प्रसाद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/जयशंकर_प्रसाद", Text = "व्यक्ति का मान नष्ट होने पर फिर नहीं मिलता।", Author = "जयशंकर प्रसाद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/जयशंकर_प्रसाद", Text = "बाहुबल ही तो वीरों की आजीविका है।", Author = "जयशंकर प्रसाद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/जयशंकर_प्रसाद", Text = "भारत समस्त विश्व का है और सम्पूर्ण वसुंधरा इसके प्रेम पाश में आबद्ध है।", Author = "जयशंकर प्रसाद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/जयशंकर_प्रसाद", Text = "मनुष्यों के मुंह में भी तो साँपों की तरह दो जीभ होते हैं।", Author = "जयशंकर प्रसाद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/जयशंकर_प्रसाद", Text = "मानव के अंतरतम में कल्याण के देवता का निवास है। उसकी संवर्धना ही उत्तम पूजा है।", Author = "जयशंकर प्रसाद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/जयशंकर_प्रसाद", Text = "मानव स्वभाव दुर्बलताओं का संकलन है।", Author = "जयशंकर प्रसाद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/जयशंकर_प्रसाद", Text = "मुझे विश्वास है कि दुराचारी सदाचार के जरिये शुद्ध हो सकता है।", Author = "जयशंकर प्रसाद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/जयशंकर_प्रसाद", Text = "राजसत्ता सुव्यवस्था से बढे तो बढ़ सकती है, केवल विजयों से नहीं।", Author = "जयशंकर प्रसाद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/जयशंकर_प्रसाद", Text = "राजा अपने राज्य की रक्षा करने में असमर्थ है, तब भी उस राज्य की रक्षा होनी ही चाहिए।", Author = "जयशंकर प्रसाद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/जयशंकर_प्रसाद", Text = "विधान की स्याही का एक बिंदु गिरकर भाग्यलिपि पर कालिमा चढ़ा देता है।", Author = "जयशंकर प्रसाद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/जयशंकर_प्रसाद", Text = "वीरता जब भागती है, तब उसके पैरों से राजनीतिक छलछद्म की धुल उड़ती है।", Author = "जयशंकर प्रसाद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/जयशंकर_प्रसाद", Text = "संदेह के गर्त में गिरने से पहले विवेक का अवलंबन ले लो।", Author = "जयशंकर प्रसाद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/जयशंकर_प्रसाद", Text = "समय बदलने पर लोगों की आँखें भी बदल जाती है।", Author = "जयशंकर प्रसाद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/जयशंकर_प्रसाद", Text = "सम्पूर्ण संसार कर्मण्य वीरों की चित्रशाला है।", Author = "जयशंकर प्रसाद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/जयशंकर_प्रसाद", Text = "संसार में छल, प्रवंचना और हत्याओं को देखकर कभी कभी मान ही लेना पड़ता है कि यह जगत ही नरक है।", Author = "जयशंकर प्रसाद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/जयशंकर_प्रसाद", Text = "सहनशील होना अच्छी बात है, पर अन्याय का विरोध करना उससे भी उत्तम है।", Author = "जयशंकर प्रसाद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/जयशंकर_प्रसाद", Text = "सेवा सबसे कठिन व्रत है।", Author = "जयशंकर प्रसाद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/जयशंकर_प्रसाद", Text = "सोने की कटार पर मुग्ध होकर उसे कोई अपने ह्रदय में डुबा नहीं सकता।", Author = "जयशंकर प्रसाद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/जयशंकर_प्रसाद", Text = "सौभाग्य और दुर्भाग्य मनुष्य की दुर्बलता के नाम हैं। मैं तो पुरुषार्थ को ही सबका नियामक समझता हूँ। पुरुषार्थ ही सौभाग्य को सींचता है।", Author = "जयशंकर प्रसाद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/जयशंकर_प्रसाद", Text = "स्त्रियों का हृदय, अभिलाषाओं का, संसार के सुखों का क्रीडा स्थल है।", Author = "जयशंकर प्रसाद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/जयशंकर_प्रसाद", Text = "स्त्री की मंत्रणा बड़ी अनुकूल और उपयोगी होती है।", Author = "जयशंकर प्रसाद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/जयशंकर_प्रसाद", Text = "स्त्री जिससे प्रेम करती है, उसी पर सर्वस्व वार देने को प्रस्तुत हो जाती है।", Author = "जयशंकर प्रसाद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/जयशंकर_प्रसाद", Text = "हृदय का सम्मिलन ही तो ब्याह है।", Author = "जयशंकर प्रसाद" },
